// Parse the incoming request
const request = $input.first().json;

// Validate required fields
const requiredFields = ['crewMember', 'conversationId', 'analysisType'];
const missingFields = requiredFields.filter(field => !request[field]);

if (missingFields.length > 0) {
  return [{
    json: {
      error: true,
      message: `Missing required fields: ${missingFields.join(', ')}`,
      statusCode: 400
    }
  }];
}

// Validate crew member - CORRECTED CREW ROSTER
const validCrewMembers = [
  'Captain Jean-Luc Picard',
  'Commander William Riker',
  'Commander Data',
  'Lieutenant Commander Geordi La Forge',
  'Lieutenant Worf',
  'Counselor Deanna Troi',
  'Dr. Beverly Crusher',
  'Lieutenant Uhura',
  'Quark'
];

if (!validCrewMembers.includes(request.crewMember)) {
  return [{
    json: {
      error: true,
      message: `Invalid crew member: ${request.crewMember}. Valid members: ${validCrewMembers.join(', ')}`,
      statusCode: 400
    }
  }];
}

// Process date range if provided
let dateRange = null;
if (request.dateRange) {
  const now = new Date();
  switch (request.dateRange) {
    case 'last_week':
      dateRange = {
        start: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000),
        end: now
      };
      break;
    case 'last_month':
      dateRange = {
        start: new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000),
        end: now
      };
      break;
    case 'last_3_months':
      dateRange = {
        start: new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000),
        end: now
      };
      break;
    default:
      if (request.startDate && request.endDate) {
        dateRange = {
          start: new Date(request.startDate),
          end: new Date(request.endDate)
        };
      }
  }
}

// Return processed request
return [{
  json: {
    error: false,
    crewMember: request.crewMember,
    conversationId: request.conversationId,
    analysisType: request.analysisType,
    dateRange: dateRange,
    specificQuestions: request.specificQuestions || [],
    timestamp: new Date().toISOString(),
    requestId: `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    crewCount: validCrewMembers.length,
    syncStatus: 'corrected'
  }
}];

// Format the crew analysis response
const analysis = $input.first().json;

// Create a structured response with sync information
const response = {
  success: true,
  crewMember: analysis.crewMember,
  conversationId: analysis.conversationId,
  analysisType: analysis.analysisType,
  timestamp: new Date().toISOString(),
  requestId: analysis.requestId,
  syncInfo: {
    crewCount: analysis.crewCount || 9,
    syncStatus: analysis.syncStatus || 'corrected',
    lastSync: new Date().toISOString()
  },
  analysis: {
    summary: analysis.summary,
    insights: analysis.insights,
    recommendations: analysis.recommendations,
    report: analysis.report
  },
  metadata: {
    processingTime: analysis.processingTime || 'N/A',
    messageCount: analysis.messageCount || 0,
    dateRange: analysis.dateRange || null
  }
};

return [{ json: response }];
